</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

const long long MOD_A = 998244353;
const long long MOD_B = 1000000007;

long long get_input() {
    long long res = 0;
    int sign = 1;
    char c = getchar();
    while (c < '0' || c > '9') {
        if (c == '-') sign = -1;
        c = getchar();
    }
    while (c >= '0' && c <= '9') {
        res = (res << 1) + (res << 3) + (c - '0');
        c = getchar();
    }
    return res * sign;
}

long long n_value;
vector<int> buckets[10];
long long prefix_sum[10];
long long counter1 = 0, counter2 = 0, total_ans = 0;
int powers[7] = {1, 10, 100, 1000, 10000, 100000, 1000000};

void generate_combinations(int length, long long value) {
    if (length > 6) return;
    buckets[length].push_back((counter1 - value + MOD_A) % MOD_A);
    prefix_sum[length] += (counter1 - value + MOD_A) % MOD_A;
    ++counter1;
    for (int digit = 0; digit <= 9; ++digit) {
        generate_combinations(length + 1, value * 10 + digit);
    }
}

bool is_valid(long long x) {
    return x * 1000000 + 999999 <= n_value && x * 10000000 > n_value;
}

void explore(int length, long long value) {
    if (value > n_value) return;
    if (is_valid(value)) {
        for (int i = 0; i <= 6; ++i) {
            long long v1 = ((counter2 + 1 - value * powers[i]) % MOD_A + MOD_A) % MOD_A;
            int idx = lower_bound(buckets[i].begin(), buckets[i].end(), (int)(MOD_A - v1)) - buckets[i].begin();
            total_ans = (total_ans + (prefix_sum[i] + buckets[i].size() * v1 - 1LL * MOD_A * (buckets[i].size() - idx))) % MOD_B;
        }
        counter2 += counter1;
    } else {
        if (length) ++counter2;
        total_ans = (total_ans + ((counter2 - value) % MOD_A + MOD_A) % MOD_A) % MOD_B;
        for (int digit = (!length); digit <= 9; ++digit) {
            explore(length + 1, value * 10 + digit);
        }
    }
}

int main() {
    n_value = get_input();
    generate_combinations(0, 0);
    for (int i = 0; i <= 6; ++i) {
        sort(buckets[i].begin(), buckets[i].end());
    }
    explore(0, 0);
    cout << total_ans << "\n";
    return 0;
}
